  ('KIMMY BOB Raw Human Hair Wig', 'kimmy-bob-raw-human-hair-wig', 'Introducing the KIMMY RAW HUMAN HAIR HD LACE Wig: Crafted with Premium Raw Straight Hair and an Undetectable Pre-Plucked High-Definition Lace for a Natural, Effortless Look. Perfect for Bosses on the Go – Wear it Glue-Less!', 41284, 41470, '["https://static.wixstatic.com/media/413b48_e4356a2abaf04b39a6eaa10c168c0c97~mv2.jpg/v1/fill/w_600,h_600,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/413b48_e4356a2abaf04b39a6eaa10c168c0c97~mv2.jpg", "https://static.wixstatic.com/media/413b48_3a81c823165e468b8752eabbd0ca2685~mv2.jpeg/v1/fill/w_600,h_600,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/413b48_3a81c823165e468b8752eabbd0ca2685~mv2.jpeg"]'::jsonb, 'wigs', NULL, true, true, 16, false, false, 4.8, 40),
